class DoublyListNode:
    def __init__(self, val):
        self.val = val
        self.next = None
        self.prev = None

def build_doubly_list(values):
    head = None
    tail = None
    for v in values:
        node = DoublyListNode(v)
        if head is None:
            head = node
            tail = node
        else:
            node.prev = tail
            tail.next = node
            tail = node
    return head

def doubly_list_to_array(head):
    result = []
    current = head
    while current is not None:
        result.append(current.val)
        current = current.next
    return result

