public class DoublyListNode
{
    public int Val;
    public DoublyListNode? Next;
    public DoublyListNode? Prev;
    public DoublyListNode(int val) { Val = val; }
}
public static class DoublyListBuilder
{
    public static DoublyListNode? FromArray(int[] values)
    {
        DoublyListNode? head = null, tail = null;
        foreach (var v in values)
        {
            var node = new DoublyListNode(v);
            if (head == null) { head = node; tail = node; }
            else { node.Prev = tail; tail!.Next = node; tail = node; }
        }
        return head;
    }
    public static int[] ToArray(DoublyListNode? head)
    {
        var result = new List<int>();
        var current = head;
        while (current != null) { result.Add(current.Val); current = current.Next; }
        return result.ToArray();
    }
}

